import{g as l}from"./Brfk6Bdo.js";import{s as n}from"./x65c5PvH.js";import{d as e,v as d,B as v,r,c as s,o as i,g as b,_ as p,u,e as _}from"./yqRbJDC7.js";const m={class:"join-block"},f=e({__name:"joinusunit-intro",setup(o){return d(()=>{const a=document.getElementById("jelly-box");if(a){const c=n(()=>{l.fromTo(a,{scaleX:1,scaleY:1},{scaleX:1.1,scaleY:.9,duration:.3,ease:"back.out(1.7)",yoyo:!0,repeat:1,onComplete:()=>{l.to(a,{scaleX:1,scaleY:1,duration:.2,ease:"power2.out"})}})},3e3);v(()=>{clearInterval(c)})}}),r(!1),(a,t)=>(i(),s("div",m,t[0]||(t[0]=[b('<h2 class="default-title" data-v-c4556bc2>如何成為試辦單位</h2><div class="line-wrapper position-relative" data-v-c4556bc2><div class="row align-items-center" data-v-c4556bc2><div class="col-lg-12 wow fadeInLeft" data-v-c4556bc2><h3 class="join-title" data-v-c4556bc2>申請資格</h3><ol class="ch-main-list join-method-list" data-v-c4556bc2><li data-v-c4556bc2>依法設立或登記滿五年之財團法人或非營利社團法人。</li><li data-v-c4556bc2> 若規畫委任私立就業服務機構，辦理外籍陪伴照顧工作者之招募、聘僱管理等事宜者，受委任之私立就業服務機構必須符合下列資格： </li><ol class="ch-sub-list" data-v-c4556bc2><li data-v-c4556bc2> 於申請日前五年內，評鑑成績依規定均屬於A級及績優免評鑑者。 </li><li data-v-c4556bc2> 於申請日前二年受雇主委任引進或聘僱之外國人，佔該機構當年總引進或聘僱外國人人數二分之一以上。 </li><li data-v-c4556bc2> 於申請日前二年，無違反就業服務法相關法規看護工及家庭幫傭。 </li></ol></ol><p class="title-p" data-v-c4556bc2> →如須瞭解符合以上資格之私立就業服務機構業者之資訊，可洽詢<a href="/contact" data-v-c4556bc2>本計畫專案辦公室</a>。 </p><h3 class="join-title" data-v-c4556bc2>評選流程</h3><p class="title-p" data-v-c4556bc2> 有意願且符合資格的單位須在勞動部公告受理期間內自行提出申請表、申請計畫書及檢附相關文件，經勞動部召開評選會議評選合格，再由勞動部視政策需要進行核定後，始得成為本計畫之試辦單位。 </p><ul class="join-method-list" data-v-c4556bc2><li data-v-c4556bc2>組織公益性及績優事蹟（20分）</li><li data-v-c4556bc2>服務內容及費用標準（15分）</li><li data-v-c4556bc2>組織專業性（15分）</li><li data-v-c4556bc2>服務品質確保機制（15分）</li><li data-v-c4556bc2>外國籍陪伴照顧服務工作者聘僱管理及訓練、後援規畫（15分）</li><li data-v-c4556bc2>創新作為（20分）</li></ul><div id="jelly-box" class="jelly-box" data-v-c4556bc2><h4 class="join-title" style="letter-spacing:1.3px;" data-v-c4556bc2>歡迎點閱，瞭解更多</h4><ul class="join-method-list" data-v-c4556bc2><li data-v-c4556bc2><a href="/conduct-plan" data-v-c4556bc2>多元陪伴照顧服務試辦計畫</a></li><li data-v-c4556bc2>試辦單位評選程序</li></ul></div><p class="title-p" data-v-c4556bc2> →如須進一步瞭解如何成為試辦單位之資訊，可洽詢本計畫<a href="/contact" data-v-c4556bc2>本計畫專案辦公室</a>。 </p></div></div></div>',2)])))}}),h=p(f,[["__scopeId","data-v-c4556bc2"]]),j={class:"main-container"},w=e({__name:"join-us-unit",setup(o){return u({title:"我要成為試辦單位 ｜ 多元陪伴照顧服務計畫"}),(a,t)=>{const c=h;return i(),s("div",j,[_(c)])}}});export{w as default};
